# RUN: llvm-mc -triple=powerpc-unknown-eabi -mcpu=e200z4 -mattr=+vle -show-encoding %s \
# RUN:   | FileCheck %s
# Expected encodings come from NXP GNU as 2.28 (-mvle -me200z4), generated by
# plans/e200/tools/gen_mc_test.py.
# Simplified mnemonics (VLEPIM Rev. 1 Appendix A, Table A-23).

# CHECK: e_nop # encoding: [0x18,0x00,0xd0,0x00]
e_nop
# CHECK: se_nop # encoding: [0x44,0x00]
se_nop
# CHECK: se_nop # encoding: [0x44,0x00]
nop
# CHECK: e_addi 3, 4, -1 # encoding: [0x18,0x64,0x84,0xff]
e_subi 3, 4, 1
# CHECK: e_add16i 3, 4, -1 # encoding: [0x1c,0x64,0xff,0xff]
e_sub16i 3, 4, 1
# CHECK: e_add2i. 3, -1 # encoding: [0x73,0xe3,0x8f,0xff]
e_sub2i. 3, 1
# CHECK: e_add2is 3, -1 # encoding: [0x73,0xe3,0x97,0xff]
e_sub2is 3, 1
# CHECK: e_addic 3, 4, -1 # encoding: [0x18,0x64,0x94,0xff]
e_subic 3, 4, 1
# CHECK: e_addic. 3, 4, -1 # encoding: [0x18,0x64,0x9c,0xff]
e_subic. 3, 4, 1
# CHECK: e_cmpi 1, 3, 5 # encoding: [0x18,0x23,0xa8,0x05]
e_cmpwi 1, 3, 5
# CHECK: e_cmpli 1, 3, 5 # encoding: [0x18,0xa3,0xa8,0x05]
e_cmplwi 1, 3, 5
# CHECK: e_rlwinm 3, 4, 0, 8, 31 # encoding: [0x74,0x83,0x02,0x3f]
e_clrlwi 3, 4, 8
# CHECK: e_rlwinm 3, 4, 0, 0, 23 # encoding: [0x74,0x83,0x00,0x2f]
e_clrrwi 3, 4, 8
# CHECK: e_rlwinm 3, 4, 4, 4, 27 # encoding: [0x74,0x83,0x21,0x37]
e_clrlslwi 3, 4, 8, 4
# CHECK: e_rlwinm 3, 4, 8, 0, 31 # encoding: [0x74,0x83,0x40,0x3f]
e_rotlwi 3, 4, 8
# CHECK: e_rlwinm 3, 4, 24, 0, 31 # encoding: [0x74,0x83,0xc0,0x3f]
e_rotrwi 3, 4, 8
# CHECK: e_rlwinm 3, 4, 4, 0, 7 # encoding: [0x74,0x83,0x20,0x0f]
e_extlwi 3, 4, 8, 4
# CHECK: e_rlwinm 3, 4, 12, 24, 31 # encoding: [0x74,0x83,0x66,0x3f]
e_extrwi 3, 4, 8, 4
# CHECK: e_rlwimi 3, 4, 28, 4, 11 # encoding: [0x74,0x83,0xe1,0x16]
e_inslwi 3, 4, 8, 4
# CHECK: e_rlwimi 3, 4, 20, 4, 11 # encoding: [0x74,0x83,0xa1,0x16]
e_insrwi 3, 4, 8, 4
# CHECK: e_crset 2 # encoding: [0x7c,0x42,0x12,0x42]
e_crset 2
# CHECK: e_crclr 2 # encoding: [0x7c,0x42,0x11,0x82]
e_crclr 2
# CHECK: e_crmove 2, 3 # encoding: [0x7c,0x43,0x1b,0x82]
e_crmove 2, 3
# CHECK: e_crnot 2, 3 # encoding: [0x7c,0x43,0x18,0x42]
e_crnot 2, 3
# CHECK: e_add16i 3, 4, 8 # encoding: [0x1c,0x64,0x00,0x08]
e_la 3, 8(4)
# CHECK: e_add16i 3, 4, -1 # encoding: [0x1c,0x64,0xff,0xff]
e_la 3, -1(4)
